<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Withdrawals</title><style>body{font-family:Arial;background:#f5f7fb;margin:0}.wrap{max-width:1250px;margin:auto;padding:25px}.card{background:#fff;padding:18px;border:1px solid #e5e7eb;border-radius:12px;margin-top:18px}input,select,button{padding:8px;border:1px solid #ddd;border-radius:6px}table{width:100%;border-collapse:collapse;margin-top:15px}th,td{padding:8px;border-bottom:1px solid #eee;text-align:left}</style></head><body><div class="wrap"><h1>Student Withdrawals</h1><a href="{{route('admin.dashboard')}}">Dashboard</a><div class="card"><form><input name="student_no" placeholder="Student ID" value="{{request('student_no')}}"><select name="status"><option value="">All Status</option><option value="Pending" @selected(request('status')==='Pending')>Pending</option><option value="Paid" @selected(request('status')==='Paid')>Paid</option><option value="Cancel" @selected(request('status')==='Cancel')>Cancel</option></select><input type="date" name="from" value="{{request('from')}}"><input type="date" name="to" value="{{request('to')}}"><button>Filter</button></form><table><tr><th>Requested</th><th>Student</th><th>WhatsApp</th><th>Points</th><th>Status</th><th>Approved</th><th>Cancelled</th><th>Action</th></tr>@foreach($items as $i)<tr><td>{{$i->requested_at}}</td><td>{{$i->student_no}} - {{$i->student_name}}</td><td>{{$i->student_whatsapp}}</td><td>{{$i->withdrawal_point}}</td><td>{{$i->approve_status}}</td><td>{{$i->approve_at}}</td><td>{{$i->cancelled_at}}</td><td>@if($i->approve_status==='Pending')<a href="{{route('admin.finance.withdrawal.process',$i->id)}}">Process</a>@else—@endif</td></tr>@endforeach</table>{{$items->links()}}</div></div></body></html>